1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Shared address handling: canonicalizes a free-text street address so equivalent
8	 * addresses written with different casing, spacing or common abbreviations are stored
9	 * and compared uniformly. Used both to normalize an owner request before it is persisted
10	 * and to compare addresses when detecting shared households (see {@link Households}).
11	 */
12	final class Addresses {
13	
14	    /** Common street-type abbreviations expanded to their full word (whole words only). */
15	    private static final Map<String, String> ABBREVIATIONS = Map.of(
16	            "ST", "STREET",
17	            "RD", "ROAD",
18	            "AVE", "AVENUE");
19	
20	    private Addresses() {
21	    }
22	
23	    /**
24	     * Returns the canonical form of {@code address}: trimmed, with every run of
25	     * whitespace collapsed to a single space, upper-cased, and common street-type
26	     * abbreviations ({@code ST}, {@code RD}, {@code AVE}) expanded to their full words.
27	     * Returns {@code null} when {@code address} is {@code null}.
28	     */
29	    static String normalize(String address) {
30	        if (address == null) {
31	            return null;
32	        }
33	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
34	        if (collapsed.isEmpty()) {
35	            return collapsed;
36	        }
37	        String[] words = collapsed.split(" ");
38	        StringBuilder result = new StringBuilder(collapsed.length());
39	        for (int i = 0; i < words.length; i++) {
40	            if (i > 0) {
41	                result.append(' ');
42	            }
43	            result.append(ABBREVIATIONS.getOrDefault(words[i], words[i]));
44	        }
45	        return result.toString();
46	    }
47	}
