1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Shared household identity. A household is keyed on an owner's last name and postcode: every
8	 * owner whose (normalized) last name and postcode match belongs to the same household and
9	 * shares one stable {@link #id household id}, derived purely from that key. The id is therefore
10	 * deterministic — two owners in the same household compute the same id independently, with no
11	 * coordination — so it drives both duplicate detection and the household-size count off a single
12	 * source of truth.
13	 */
14	final class Households {
15	
16	    private Households() {
17	    }
18	
19	    /**
20	     * Canonicalizes a last name for case-insensitive, whitespace-insensitive comparison:
21	     * trims the ends, collapses every run of whitespace to a single space and lower-cases
22	     * the result. Returns an empty string when {@code lastName} is {@code null}.
23	     */
24	    private static String normalizeName(String lastName) {
25	        if (lastName == null) {
26	            return "";
27	        }
28	        return lastName.trim().replaceAll("\\s+", " ").toLowerCase();
29	    }
30	
31	    /**
32	     * The stable household id shared by every owner with the same last name and postcode: the
33	     * first 12 hex characters of the SHA-256 digest of {@code normalizedLastName + "|" +
34	     * postcode}. A {@code null} postcode contributes an empty segment.
35	     */
36	    static String id(String lastName, String postcode) {
37	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
38	        return Hashes.upperHexPrefix(key, 12);
39	    }
40	
41	    /** The household id a create request resolves to, from its last name and postcode. */
42	    static String id(OwnerFieldsDto request) {
43	        return id(request.getLastName(), request.getPostcode());
44	    }
45	
46	    /** The household id of an existing owner, from its stored last name and postcode. */
47	    static String id(Owner owner) {
48	        return id(owner.getLastName(), owner.getPostcode());
49	    }
50	
51	    /** Whether the two owners belong to the same household (identical household id). */
52	    static boolean sameHousehold(Owner a, Owner b) {
53	        return id(a).equals(id(b));
54	    }
55	}
