6	/**
7	 * Rejects a request whose supplied postcode is malformed or out of range for the owner's city
8	 * (see {@link Postcodes}). A postcode is optional: an absent postcode passes unchanged, keeping
9	 * the request contract backward-compatible.
10	 */
11	public class ValidateOwnerPostcode {
12	
13	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
14	        String postcode = request.getPostcode();
15	        if (postcode == null) {
16	            return;
17	        }
18	        if (!Postcodes.isValidForCity(postcode, request.getCity())) {
19	            throw new InvalidPostcodeException(postcode, request.getCity());
20	        }
21	    }
22	}
