5	/**
6	 * The derived key summarising an owner's identity for display: {@code normalizedTelephone +
7	 * "|" + (email or empty) + "|" + householdId}, canonicalizing each part the same way it is
8	 * stored (E.164 telephone, lower-cased email, deterministic household id). Duplicate rejection
9	 * itself is keyed on the household alone (see {@link EnsureUniqueHousehold}); this key exposes
10	 * the full derivation on the response.
11	 */
12	public final class IdentityKeys {
13	
14	    private IdentityKeys() {
15	    }
16	
17	    /**
18	     * The identity key of an existing owner, derived from its stored fields.
19	     */
20	    public static String of(Owner owner) {
21	        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
22	    }
23	
24	    private static String key(String telephone, String email, String householdId) {
25	        String normalizedTelephone = telephone == null ? ""
26	                : Telephones.toE164(telephone).orElse(telephone);
27	        String normalizedEmail = email == null || email.isBlank() ? "" : Emails.normalize(email);
28	        String household = householdId == null ? "" : householdId;
29	        return normalizedTelephone + "|" + normalizedEmail + "|" + household;
30	    }
31	}
