2	
3	import java.util.Optional;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Soft duplicate matching: a new owner is a <em>possible</em> duplicate of an existing owner
10	 * when they belong to the same {@link Households household} (same last name and postcode) yet
11	 * were given a different telephone number.
12	 *
13	 * <p>Unlike a household duplicate (see {@link EnsureUniqueHousehold}), which is rejected
14	 * outright, a possible duplicate that reaches this point has declared {@code sharesHousehold};
15	 * it is still created and merely flagged with the id of the owner it resembles. The differing
16	 * telephone is what distinguishes it from an exact re-registration.
17	 */
18	final class PossibleDuplicates {
19	
20	    private PossibleDuplicates() {
21	    }
22	
23	    /**
24	     * The id of the earliest existing owner the given owner possibly duplicates — same
25	     * household, different telephone — or empty when there is no such owner.
26	     */
27	    static Optional<Integer> matchFor(Owner owner, OwnerRepository ownerRepository) {
28	        Owner match = null;
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (matches(owner, existing) && (match == null || existing.getId() < match.getId())) {
31	                match = existing;
32	            }
33	        }
34	        return Optional.ofNullable(match).map(Owner::getId);
35	    }
36	
37	    private static boolean matches(Owner owner, Owner existing) {
38	        return Households.sameHousehold(owner, existing)
39	                && !sameTelephone(owner.getTelephone(), existing.getTelephone());
40	    }
41	
42	    private static boolean sameTelephone(String a, String b) {
43	        return a != null && a.equals(b);
44	    }
45	}
